impl<'a> ListNode<'a> for Plus0<'a> {
    fn iter(&'a self) -> IntoIter<ParseTree<'a>> {
        let mut items = vec![];
        let mut current = self;
        loop {
            match current {
                Plus0::Alt0 {
                    stmts_0: rest,
                    ws,
                    stmt_2: item,
                    ..
                } => {
                    items.push(item.as_parse_tree());
                    items.push(ws.as_parse_tree());
                    current = rest;
                }
                Plus0::Alt1 { stmt: item, .. } => {
                    items.push(item.as_parse_tree());
                    break;
                }
                Plus0::Amb(_) => {
                    items.push(ParseTree::Plus0(current));
                    break;
                }
            }
        }
        items.reverse();
        items.into_iter()
    }
}
impl<'a> ListNode<'a> for Group0<'a> {
    fn iter(&'a self) -> IntoIter<ParseTree<'a>> {
        match self {
            Group0::Alt0 {
                lit_0, ws, stmt, ..
            } => vec![
                lit_0.as_parse_tree(),
                ws.as_parse_tree(),
                stmt.as_parse_tree(),
            ]
            .into_iter(),
            Group0::Amb(_) => vec![ParseTree::Group0(self)].into_iter(),
        }
    }
}
impl<'a> OptNode for Opt0<'a> {
    type Inner = Group0<'a>;
    fn value(&self) -> Option<&Self::Inner> {
        match self {
            Opt0::Alt0 { group_0, .. } => Some(group_0),
            Opt0::Alt1 { .. } => None,
            Opt0::Amb(_) => panic!("unexpected ambiguity in optional node"),
        }
    }
}
impl<'a> Expr<'a> {
    pub fn as_id(&self) -> Option<&Token> {
        match self {
            Expr::Id { id, .. } => Some(id),
            _ => None,
        }
    }
    pub fn as_num(&self) -> Option<&Token> {
        match self {
            Expr::Num { num, .. } => Some(num),
            _ => None,
        }
    }
}
#[derive(Debug, Clone, Copy)]
pub struct Token {
    pub kind: TokenKind,
    span: Span,
}
impl Token {
    pub fn as_parse_tree<'a>(&self) -> ParseTree<'a> {
        ParseTree::Token(*self)
    }
    pub fn span(&self) -> Span {
        self.span
    }
}
fn token_kind(terminal_id: TerminalId) -> TokenKind {
    match terminal_id {
        // Id
        TerminalId(0) => TokenKind::T0,
        // Num
        TerminalId(1) => TokenKind::T1,
        // WS
        TerminalId(2) => TokenKind::T2,
        // ";"
        TerminalId(3) => TokenKind::T3,
        // "if"
        TerminalId(4) => TokenKind::T4,
        // "("
        TerminalId(5) => TokenKind::T5,
        // ")"
        TerminalId(6) => TokenKind::T6,
        // "else"
        TerminalId(7) => TokenKind::T7,
        // "assert"
        TerminalId(8) => TokenKind::T8,
        // [0-9 A-Z _ a-z]
        TerminalId(9) => TokenKind::T9,
        _ => unreachable!("Unknown TerminalId: {:?}", terminal_id),
    }
}
pub struct ExactKeywordParseTreeBuilder<'a> {
    pub arena: &'a Arena,
}
impl<'a> ExactKeywordParseTreeBuilder<'a> {
    pub fn new(tree_arena: &'a Arena) -> Self {
        Self { arena: tree_arena }
    }
}
impl<'a> ParseTreeBuilder<ParseTree<'a>> for ExactKeywordParseTreeBuilder<'a> {
    fn new_nonterminal_node(
        &self,
        nonterminal_node: &NonterminalNode,
        children: OneOrMany<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        match nonterminal_node.nonterminal_id {
            // Program
            NonterminalId(0) => match nonterminal_node.return_slot {
                // Program : Stmt+.
                SlotId(1) => {
                    let [stmts] = children.into_array::<1usize>();
                    ParseTree::Program(self.arena.alloc(Program::Alt0 {
                        stmts: stmts.unwrap_plus_0(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Stmt
            NonterminalId(1) => match nonterminal_node.return_slot {
                // Stmt : Expr WS ";".
                SlotId(5) => {
                    let [expr, ws, lit_2] = children.into_array::<3usize>();
                    ParseTree::Stmt(self.arena.alloc(Stmt::Expr {
                        expr: expr.unwrap_expr(),
                        ws: ws.unwrap_token(),
                        lit_2: lit_2.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                // Stmt : [0-9 A-Z _ a-z] !<< "if" !>> [0-9 A-Z _ a-z] WS "(" WS Expr WS ")" WS Stmt WS ([0-9
                // A-Z _ a-z] !<< "else" !>> [0-9 A-Z _ a-z] Stmt)?.
                SlotId(17) => {
                    let [
                        lit_0,
                        ws_1,
                        lit_2,
                        ws_3,
                        expr,
                        ws_5,
                        lit_6,
                        ws_7,
                        stmt,
                        ws_9,
                        opt_0,
                    ] = children.into_array::<11usize>();
                    ParseTree::Stmt(self.arena.alloc(Stmt::If {
                        lit_0: lit_0.unwrap_token(),
                        ws_1: ws_1.unwrap_token(),
                        lit_2: lit_2.unwrap_token(),
                        ws_3: ws_3.unwrap_token(),
                        expr: expr.unwrap_expr(),
                        ws_5: ws_5.unwrap_token(),
                        lit_6: lit_6.unwrap_token(),
                        ws_7: ws_7.unwrap_token(),
                        stmt: stmt.unwrap_stmt(),
                        ws_9: ws_9.unwrap_token(),
                        opt_0: opt_0.unwrap_opt_0(),
                        span: nonterminal_node.span,
                    }))
                }
                // Stmt : [0-9 A-Z _ a-z] !<< "assert" !>> [0-9 A-Z _ a-z] WS Expr WS ";".
                SlotId(23) => {
                    let [lit_0, ws_1, expr, ws_3, lit_4] = children.into_array::<5usize>();
                    ParseTree::Stmt(self.arena.alloc(Stmt::Assert {
                        lit_0: lit_0.unwrap_token(),
                        ws_1: ws_1.unwrap_token(),
                        expr: expr.unwrap_expr(),
                        ws_3: ws_3.unwrap_token(),
                        lit_4: lit_4.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Expr
            NonterminalId(2) => match nonterminal_node.return_slot {
                // Expr : Id.
                SlotId(25) => {
                    let [id] = children.into_array::<1usize>();
                    ParseTree::Expr(self.arena.alloc(Expr::Id {
                        id: id.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                // Expr : Num.
                SlotId(27) => {
                    let [num] = children.into_array::<1usize>();
                    ParseTree::Expr(self.arena.alloc(Expr::Num {
                        num: num.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Plus_0
            NonterminalId(3) => match nonterminal_node.return_slot {
                // Stmt+ : Stmt+ WS Stmt.
                SlotId(31) => {
                    let [stmts_0, ws, stmt_2] = children.into_array::<3usize>();
                    ParseTree::Plus0(self.arena.alloc(Plus0::Alt0 {
                        stmts_0: stmts_0.unwrap_plus_0(),
                        ws: ws.unwrap_token(),
                        stmt_2: stmt_2.unwrap_stmt(),
                        span: nonterminal_node.span,
                    }))
                }
                // Stmt+ : Stmt.
                SlotId(33) => {
                    let [stmt] = children.into_array::<1usize>();
                    ParseTree::Plus0(self.arena.alloc(Plus0::Alt1 {
                        stmt: stmt.unwrap_stmt(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Group_0
            NonterminalId(4) => match nonterminal_node.return_slot {
                // ([0-9 A-Z _ a-z] !<< "else" !>> [0-9 A-Z _ a-z] Stmt) : [0-9 A-Z _ a-z] !<< "else" !>>
                // [0-9 A-Z _ a-z] WS Stmt.
                SlotId(37) => {
                    let [lit_0, ws, stmt] = children.into_array::<3usize>();
                    ParseTree::Group0(self.arena.alloc(Group0::Alt0 {
                        lit_0: lit_0.unwrap_token(),
                        ws: ws.unwrap_token(),
                        stmt: stmt.unwrap_stmt(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Opt_0
            NonterminalId(5) => match nonterminal_node.return_slot {
                // ([0-9 A-Z _ a-z] !<< "else" !>> [0-9 A-Z _ a-z] Stmt)? : ([0-9 A-Z _ a-z] !<< "else" !>>
                // [0-9 A-Z _ a-z] Stmt).
                SlotId(39) => {
                    let [group_0] = children.into_array::<1usize>();
                    ParseTree::Opt0(self.arena.alloc(Opt0::Alt0 {
                        group_0: group_0.unwrap_group_0(),
                        span: nonterminal_node.span,
                    }))
                }
                // ([0-9 A-Z _ a-z] !<< "else" !>> [0-9 A-Z _ a-z] Stmt)? : .
                SlotId(40) => {
                    let [] = children.into_array::<0usize>();
                    ParseTree::Opt0(self.arena.alloc(Opt0::Alt1 {
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // StartProgram
            NonterminalId(6) => match nonterminal_node.return_slot {
                // Program : WS start:Program WS.
                SlotId(44) => {
                    let [ws_0, start, ws_2] = children.into_array::<3usize>();
                    ParseTree::StartProgram(self.arena.alloc(Start {
                        before: ws_0.unwrap_token(),
                        node: start.unwrap_program(),
                        after: ws_2.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // StartStmt
            NonterminalId(7) => match nonterminal_node.return_slot {
                // Stmt : WS start:Stmt WS.
                SlotId(48) => {
                    let [ws_0, start, ws_2] = children.into_array::<3usize>();
                    ParseTree::StartStmt(self.arena.alloc(Start {
                        before: ws_0.unwrap_token(),
                        node: start.unwrap_stmt(),
                        after: ws_2.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // StartExpr
            NonterminalId(8) => match nonterminal_node.return_slot {
                // Expr : WS start:Expr WS.
                SlotId(52) => {
                    let [ws_0, start, ws_2] = children.into_array::<3usize>();
                    ParseTree::StartExpr(self.arena.alloc(Start {
                        before: ws_0.unwrap_token(),
                        node: start.unwrap_expr(),
                        after: ws_2.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            _ => unreachable!(),
        }
    }
    fn new_token(&self, terminal_node: &TerminalNode) -> ParseTree<'a> {
        ParseTree::Token(Token {
            kind: token_kind(terminal_node.terminal_id),
            span: terminal_node.span,
        })
    }
    fn new_ambiguity_node(
        &self,
        parent: NonterminalId,
        alternatives: Vec<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        match parent {
            crate::grammar_data::PROGRAM => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_program()));
                ParseTree::Program(self.arena.alloc(Program::Amb(slice)))
            }
            crate::grammar_data::STMT => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_stmt()));
                ParseTree::Stmt(self.arena.alloc(Stmt::Amb(slice)))
            }
            crate::grammar_data::EXPR => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_expr()));
                ParseTree::Expr(self.arena.alloc(Expr::Amb(slice)))
            }
            crate::grammar_data::PLUS_0 => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_plus_0()));
                ParseTree::Plus0(self.arena.alloc(Plus0::Amb(slice)))
            }
            crate::grammar_data::GROUP_0 => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_group_0()));
                ParseTree::Group0(self.arena.alloc(Group0::Amb(slice)))
            }
            crate::grammar_data::OPT_0 => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_opt_0()));
                ParseTree::Opt0(self.arena.alloc(Opt0::Amb(slice)))
            }
            crate::grammar_data::START_PROGRAM => {
                let first = alternatives[0].unwrap_start_program();
                let inner = self.arena.alloc_slice(
                    alternatives
                        .into_iter()
                        .map(|a| a.unwrap_start_program().node),
                );
                let node = &*self.arena.alloc(Program::Amb(inner));
                ParseTree::StartProgram(self.arena.alloc(Start {
                    before: first.before,
                    node,
                    after: first.after,
                    span: first.span,
                }))
            }
            crate::grammar_data::START_STMT => {
                let first = alternatives[0].unwrap_start_stmt();
                let inner = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_start_stmt().node));
                let node = &*self.arena.alloc(Stmt::Amb(inner));
                ParseTree::StartStmt(self.arena.alloc(Start {
                    before: first.before,
                    node,
                    after: first.after,
                    span: first.span,
                }))
            }
            crate::grammar_data::START_EXPR => {
                let first = alternatives[0].unwrap_start_expr();
                let inner = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_start_expr().node));
                let node = &*self.arena.alloc(Expr::Amb(inner));
                ParseTree::StartExpr(self.arena.alloc(Start {
                    before: first.before,
                    node,
                    after: first.after,
                    span: first.span,
                }))
            }
            _ => unreachable!("nonterminal cannot be ambiguous"),
        }
    }
}
pub fn create_parse_tree<'a>(
    root_id: SPPFNodeId,
    nonterminal_id: NonterminalId,
    parser: &ExactKeywordParser,
    builder: &ExactKeywordParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    match nonterminal_id {
        crate::grammar_data::PROGRAM => {
            ParseTree::Program(create_parse_tree_program(root_id, parser, builder))
        }
        crate::grammar_data::STMT => {
            ParseTree::Stmt(create_parse_tree_stmt(root_id, parser, builder))
        }
        crate::grammar_data::EXPR => {
            ParseTree::Expr(create_parse_tree_expr(root_id, parser, builder))
        }
        crate::grammar_data::PLUS_0 => {
            ParseTree::Plus0(create_parse_tree_plus_0(root_id, parser, builder))
        }
        crate::grammar_data::GROUP_0 => {
            ParseTree::Group0(create_parse_tree_group_0(root_id, parser, builder))
        }
        crate::grammar_data::OPT_0 => {
            ParseTree::Opt0(create_parse_tree_opt_0(root_id, parser, builder))
        }
        crate::grammar_data::START_PROGRAM => {
            ParseTree::StartProgram(create_parse_tree_start_program(root_id, parser, builder))
        }
        crate::grammar_data::START_STMT => {
            ParseTree::StartStmt(create_parse_tree_start_stmt(root_id, parser, builder))
        }
        crate::grammar_data::START_EXPR => {
            ParseTree::StartExpr(create_parse_tree_start_expr(root_id, parser, builder))
        }
        _ => panic!(),
    }
}
